export const BEHAVIORS_CSS = "/* Histeon behaviours (docs/spec/interactions.md): only what the script needs; hidden states apply only with it. */\n@media (prefers-reduced-motion: no-preference) {\n  .xb-js [data-xb-reveal] {\n    transition: opacity 0.6s ease, transform 0.6s ease;\n  }\n  .xb-js [data-xb-reveal]:not(.is-visible) {\n    opacity: 0;\n    transform: translateY(var(--xb-reveal-shift, 1.5rem));\n  }\n}\n\n/* Videos (E9): the poster fills the box, the player takes its place on click. */\n[data-xb-video] {\n  position: relative;\n  aspect-ratio: 16 / 9;\n  overflow: hidden;\n  background: #111;\n}\n[data-xb-video] > a {\n  display: block;\n  width: 100%;\n  height: 100%;\n}\n[data-xb-video] > a img,\n[data-xb-video] .xb-video__frame {\n  display: block;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  border: 0;\n}\n[data-xb-video] .xb-video__icon {\n  position: absolute;\n  inset: 50% auto auto 50%;\n  width: 68px;\n  height: 48px;\n  margin: -24px 0 0 -34px;\n  border-radius: 12px;\n  background: rgb(0 0 0 / 0.72);\n}\n[data-xb-video] .xb-video__icon::after {\n  content: '';\n  position: absolute;\n  inset: 14px auto auto 27px;\n  border-style: solid;\n  border-width: 10px 0 10px 17px;\n  border-color: transparent transparent transparent #fff;\n}\n[data-xb-video] > a:hover .xb-video__icon,\n[data-xb-video] > a:focus-visible .xb-video__icon {\n  background: #e33;\n}\n\n/* Maps (E11): a box with the place's name until the click loads the map. */\n[data-xb-map] {\n  position: relative;\n  aspect-ratio: 4 / 3;\n  margin: 0;\n  overflow: hidden;\n  background: repeating-linear-gradient(45deg, #e8ece9 0 12px, #dfe5e1 12px 24px);\n}\n[data-xb-map] > a {\n  display: grid;\n  place-content: center;\n  gap: 0.4em;\n  width: 100%;\n  height: 100%;\n  text-align: center;\n  color: inherit;\n  text-decoration: none;\n}\n[data-xb-map] .xb-map__label {\n  font-weight: 600;\n}\n[data-xb-map] .xb-map__hint {\n  font-size: 0.85em;\n  text-decoration: underline;\n}\n[data-xb-map] .xb-map__frame {\n  display: block;\n  width: 100%;\n  height: 100%;\n  border: 0;\n}\n";
